                    } else {
                        $errorMessage = t('timed_messages_err_update_failed');
                    }
                    $stmt->close();
                } catch (mysqli_sql_exception $e) {
                    $errorMessage = t('timed_messages_err_updating') . $e->getMessage();
                }
            } else {
                $errorMessage = t('timed_messages_err_invalid_input');
